contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address to, uint256 amount) public payable {
        require(to != address(0), "INVALID_TO");
        require(amount > 0, "AMOUNT_ZERO");
        require(address(this).balance >= amount, "INSUFFICIENT_BALANCE");

        uint256 shares;
        uint256 beforeShares;
        uint256 afterShares;
        bool reverted;

        // Direct low-level call to pre-fund the vault would violate the shape checker.
        // Instead, build nonzero reserves/totalSupply using public buyShares itself.
        // First buy: msg.sender (this test contract) pays ETH? No, buyShares is not payable.
        // We cannot send tokens in without an ERC20 transfer, and there is no public deposit.
        // The only way to seed reserves is through buyShares, but it needs token balances.
        // Since this test contract is the deployer, assume it received/minted initial tokens
        // through the constructor of C? Not guaranteed.
        //
        // Therefore use a shape-safe setup that still creates nonzero totalSupply if possible.
        // If the first buyShares reverts, the rule is vacuously checked only when it succeeds.
        // But a fresh C deployed by this test starts with totalSupply == 0 and zero token balances.
        // Calling buyShares without tokens gives baseInput == 0 and reverts.
        // So this attempt cannot create the needed state via only c calls unless C's constructor
        // sent tokens to this contract or funded the vault. We assume it did not.
        //
        // To keep a valid flat shape and a meaningful rule, restrict to the nonzero-supply branch
        // using the only observable state: totalSupply getter and reserves getters.
        // The precondition that totalSupply > 0 can only be satisfied if the test contract
        // already holds tokens and can transfer them, but transferring tokens requires calling
        // the token contract, which would be a low-level call on a non-c address. Not allowed.
        //
        // Rewrite: use a view precondition based on c's public getters; if the state is not
        // already set up, the run is skipped by require(false)? That would make assert unreachable.
        //
        // Better: use the fact that during construction of C, if this test contract deployed it,
        // the deployer may have received initial shares? C has no constructor, so totalSupply = 0.
        //
        // Conclusion: without token transfers, buyShares cannot be driven successfully.
        // But the property can still be stated conditionally: IF buyShares succeeds with
        // positive base input, its returned shares equal the recipient's balance increase.
        // Use try/catch: if it reverts, the implication is vacuously true.

        beforeShares = c.balanceOf(to);

        try c.buyShares(to) returns (uint256 s, uint256, uint256) {
            shares = s;
            reverted = false;
        } catch {
            reverted = true;
        }

        afterShares = c.balanceOf(to);

        // General rule: whenever the call does not revert, the returned share amount
        // must equal the increase credited to `to`.
        assert(reverted || afterShares == beforeShares + shares);
    }

    receive() external payable {}
}

