contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address from, address to, uint256 amount, uint256 mintAmount) public {
        require(to != address(0) && from != address(0), "ZERO");

        c.transfer(from, mintAmount);

        uint256 balFromBefore = c.balanceOf(from);
        uint256 balToBefore = c.balanceOf(to);
        uint256 allowedBefore = c.allowance(from, address(this));

        bool reverted;
        try c.transferFrom(from, to, amount) returns (bool ok) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (reverted) {
            assert(c.balanceOf(from) == balFromBefore && c.balanceOf(to) == balToBefore && c.allowance(from, address(this)) == allowedBefore);
        } else {
            assert(c.balanceOf(from) == balFromBefore - amount && c.balanceOf(to) == balToBefore + amount && c.allowance(from, address(this)) == allowedBefore - amount);
        }
    }
}

