contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address to, uint256 baseAmount, uint256 quoteAmount) public payable {
        require(to != address(0), "ZERO_RECIPIENT");
        require(baseAmount > 0, "NO_BASE_INPUT");

        // Seed the pool with initial tokens via a genuine buyShares call.
        (bool success0, ) = address(c).call(
            abi.encodeWithSignature("buyShares(address)", address(this))
        );
        require(success0, "SEED_FAILED");

        uint256 supplyBefore = c.totalSupply();
        uint256 balanceBefore = c.balanceOf(to);

        // The deciding call: buy more shares for `to` (non-zero recipient).
        (bool success, bytes memory returndata) = address(c).call(
            abi.encodeWithSignature("buyShares(address)", to)
        );
        if (success) {
            (uint256 shares, uint256 baseInput, uint256 quoteInput) =
                abi.decode(returndata, (uint256, uint256, uint256));
            uint256 supplyAfter = c.totalSupply();
            uint256 balanceAfter = c.balanceOf(to);

            assert(balanceAfter >= balanceBefore + shares);
            assert(supplyAfter >= supplyBefore + shares);
        } else {
            assert(true);
        }
    }

    receive() external payable {}
}

