contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 buySeed, uint256 sellSeed) public payable {
        require(buySeed > 1e18, "buySeed too small");

        uint256 totalSupplyBefore = c.totalSupply();
        uint256 sharesReturned;
        bool buyReverted;
        try c.buyShares(address(this)) returns (uint256 s, uint256 b, uint256 q) {
            buyReverted = false;
            sharesReturned = s;
        } catch {
            buyReverted = true;
        }

        uint256 totalSupplyAfterBuy = c.totalSupply();
        if (!buyReverted) {
            require(totalSupplyAfterBuy >= totalSupplyBefore + sharesReturned, "buyShares did not increase totalSupply by at least shares");
        } else {
            require(totalSupplyAfterBuy == totalSupplyBefore, "reverted buyShares changed totalSupply");
        }

        uint256 sharesOnAccount = c.balanceOf(address(this));
        require(sharesOnAccount > 0, "no shares to sell");

        uint256 sellAmount = sharesOnAccount - 1;
        uint256 totalSupplyBeforeSell = c.totalSupply();
        bool sellReverted;
        try c.sellShares(sellAmount, address(this), 0, 0, "", block.timestamp + 1000) returns (uint256 ba, uint256 qa) {
            sellReverted = false;
        } catch {
            sellReverted = true;
        }

        uint256 totalSupplyAfterSell = c.totalSupply();
        if (!sellReverted) {
            assert(totalSupplyAfterSell == totalSupplyBeforeSell - sellAmount);
        } else {
            assert(totalSupplyAfterSell == totalSupplyBeforeSell);
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run() public payable {
        uint256 sharesBefore = c.balanceOf(address(this));
        uint256 totalSupplyBefore = c.totalSupply();

        bool buyReverted;
        uint256 sharesReturned;
        try c.buyShares(address(this)) returns (uint256 s, uint256 b, uint256 q) {
            buyReverted = false;
            sharesReturned = s;
        } catch {
            buyReverted = true;
        }

        uint256 sharesAfter = c.balanceOf(address(this));
        uint256 totalSupplyAfter = c.totalSupply();

        assert(!buyReverted
            ? (sharesAfter >= sharesBefore + sharesReturned && totalSupplyAfter >= totalSupplyBefore + sharesReturned)
            : (sharesAfter == sharesBefore && totalSupplyAfter == totalSupplyBefore));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 shareAmount, uint256 baseMinAmount, uint256 quoteMinAmount) public payable {
        require(shareAmount > 0, "zero amount");

        uint256 balBeforeCaller = c.balanceOf(address(this));
        require(shareAmount <= balBeforeCaller, "not enough shares");

        uint256 supplyBefore = c.totalSupply();

        bool reverted;
        try c.sellShares(shareAmount, address(this), baseMinAmount, quoteMinAmount, "", block.timestamp) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 balAfterCaller = c.balanceOf(address(this));
        uint256 supplyAfter = c.totalSupply();

        assert(reverted
            ? (balAfterCaller == balBeforeCaller && supplyAfter == supplyBefore)
            : (balAfterCaller == balBeforeCaller - shareAmount && supplyAfter == supplyBefore - shareAmount));
    }

    receive() external payable {}
}

